import base64
import binascii
import re

from gmssl import sm4


def sm4_encrypt(plaintext: str, key_hex: str) -> str:
    """
    SM4加密函数（ECB模式+PKCS#7填充）

    参数:
        plaintext: 待加密的明文字符串
        key_hex: 十六进制格式的SM4密钥（16字节/32个十六进制字符）

    返回:
        加密后的十六进制字符串（小写）
    """
    # 1. 将密钥从十六进制字符串转换为字节
    key_bytes = bytes.fromhex(key_hex)

    # 2. 初始化SM4加密器
    sm4_cipher = sm4.CryptSM4()
    sm4_cipher.set_key(key_bytes, sm4.SM4_ENCRYPT)  # 设置为加密模式

    # 3. 将明文转换为UTF-8编码的字节
    plaintext_bytes = plaintext.encode('utf-8')

    # 4. 执行ECB模式加密（SM4-ECB不需要IV）
    ciphertext_bytes = sm4_cipher.crypt_ecb(plaintext_bytes)

    # 5. 将加密结果转换为小写十六进制字符串并返回
    return ciphertext_bytes.hex().lower()


import time
import random
import urllib.parse
import math


class UUIDGenerator:
    """对应JS中的T对象，实现UUID生成逻辑"""

    @staticmethod
    def max_from_bits(bits: int) -> int:
        """计算指定位数能表示的最大值"""
        return int(math.pow(2, bits))

    # 各种位数的最大值
    limit_ui04 = max_from_bits(4)
    limit_ui06 = max_from_bits(6)
    limit_ui08 = max_from_bits(8)
    limit_ui12 = max_from_bits(12)
    limit_ui16 = max_from_bits(16)
    limit_ui32 = max_from_bits(32)
    limit_ui48 = max_from_bits(48)

    @staticmethod
    def random_int(min_val: int, max_val: int) -> int:
        """生成指定范围的随机整数"""
        return random.randint(min_val, max_val)

    @staticmethod
    def random_ui04() -> int:
        return UUIDGenerator.random_int(0, UUIDGenerator.limit_ui04 - 1)

    @staticmethod
    def random_ui06() -> int:
        return UUIDGenerator.random_int(0, UUIDGenerator.limit_ui06 - 1)

    @staticmethod
    def random_ui08() -> int:
        return UUIDGenerator.random_int(0, UUIDGenerator.limit_ui08 - 1)

    @staticmethod
    def random_ui12() -> int:
        return UUIDGenerator.random_int(0, UUIDGenerator.limit_ui12 - 1)

    @staticmethod
    def random_ui16() -> int:
        return UUIDGenerator.random_int(0, UUIDGenerator.limit_ui16 - 1)

    @staticmethod
    def random_ui32() -> int:
        return UUIDGenerator.random_int(0, UUIDGenerator.limit_ui32 - 1)

    @staticmethod
    def random_ui48() -> int:
        """生成48位随机整数"""
        return (random.getrandbits(30) << 18) | random.getrandbits(18)

    @staticmethod
    def padded_string(value: int, length: int, pad_char: str = "0") -> str:
        """将数值转换为指定长度的十六进制字符串，不足补零"""
        hex_str = format(value, 'x')
        if len(hex_str) < length:
            hex_str = pad_char * (length - len(hex_str)) + hex_str
        return hex_str

    @classmethod
    def create_v4(cls) -> str:
        """生成UUID v4（对应JS中的T._create4）"""
        # 生成各个部分的随机数
        part1 = cls.random_ui32()
        part2 = cls.random_ui16()
        part3 = 0x4000 | cls.random_ui12()  # 版本号4
        part4 = 0x80 | cls.random_ui06()  # 变体标识
        part5 = cls.random_ui08()
        part6 = cls.random_ui48()

        # 格式化为UUID字符串
        hex_str = (
            f"{cls.padded_string(part1, 8)}-"
            f"{cls.padded_string(part2, 4)}-"
            f"{cls.padded_string(part3, 4)}-"
            f"{cls.padded_string(part4, 2)}{cls.padded_string(part5, 2)}-"
            f"{cls.padded_string(part6, 12)}"
        )
        return hex_str


def uuid() -> str:
    """对应JS中的H.uuid()，生成无连字符的UUID v4"""
    return UUIDGenerator.create_v4().replace('-', '')


def time_stamp() -> int:
    """对应JS中的H.timeStamp()，返回当前时间毫秒数"""
    return int(time.time() * 1000)


def get_sort_string(params: dict) -> str:
    """对应JS中的H.getSortString()，对参数排序并拼接"""
    # 对字典键进行排序
    sorted_keys = sorted(params.keys())
    sorted_params = {k: params[k] for k in sorted_keys}

    # 拼接为key=value&key=value格式（过滤空值）
    parts = []
    for key, value in sorted_params.items():
        if value is not None and str(value).strip() != "":
            parts.append(f"{key}={value}")
    return "&".join(parts) if parts else ""


def get_query_string(params: dict) -> str:
    """对应JS中的H.getQueryString()，生成URL查询字符串"""
    parts = []
    for key, value in params.items():
        if value is not None:
            # 对应JS的encodeURIComponent
            encoded_value = urllib.parse.quote(str(value), safe='')
            parts.append(f"{key}={encoded_value}")
    return "&".join(parts) if parts else ""


def sm2_encrypt(sm4_key, target_public_key):
    """
    使用SM2公钥加密SM4密钥

    参数:
        sm4_key: 待加密的SM4密钥（字符串格式）
        target_public_key: 接收方的SM2公钥（用于加密，十六进制字符串）

    返回:
        加密后的SM4密钥（十六进制字符串）
    """
    # 1. 创建SM2加密对象（使用接收方公钥，己方私钥为空）
    # 注意：加密模式需与解密保持一致（mode=1）
    sm2_crypt = sm2.CryptSM2(
        private_key='7faa61bb9051707ad9d9d2c417d61e038a3af871a61c8da534a9061ac1e51c32',  # 加密时不需要己方私钥
        public_key=target_public_key,
        mode=1  # 与解密模式保持一致
    )

    # 2. 将SM4密钥转为字节流
    sm4_key_bytes = sm4_key.encode('utf-8')

    # 3. 执行SM2加密（返回字节流）
    encrypted_bytes = sm2_crypt.encrypt(sm4_key_bytes)

    # 4. 将加密结果转为十六进制字符串返回（便于传输存储）
    return binascii.hexlify(encrypted_bytes).decode()


def zi(t: str) -> str:
    """对应JS中的Zi函数，处理SM2签名结果"""

    def xi(s: str) -> str:
        return re.sub(r'[^0-9a-fA-F]', '', s).lower()

    def dollar_i(s: str) -> str:
        s = s.ljust(64, '0') if len(s) < 64 else s[:64]
        return s.ljust(64, '0')

    def yi(s: str) -> str:
        return xi(s)

    comma_index = t.index(',') if ',' in t else -1

    if comma_index > -1:
        part1 = xi(t[:comma_index])
        part2 = xi(t[comma_index + 1:])
        return f"{dollar_i(part1)}{dollar_i(part2)}"
    else:
        mid = len(t) // 2
        part1 = yi(t[:mid])
        part2 = yi(t[mid:])
        return f"{part1},{part2}"


from gmssl import sm2


# ===== 工具函数 =====
def Xi(t: str) -> str:
    """十进制字符串 -> 十六进制字符串"""
    return format(int(t, 10), "x")


def Yi(t: str) -> str:
    """十六进制字符串 -> 十进制字符串"""
    return str(int(t, 16))


def pad64(s: str) -> str:
    """左补零到长度 64"""
    return s.zfill(64)


def Zi(t: str) -> str:
    """
    Python 版 Zi
    JS逻辑:
    - 如果 t 含逗号: 按逗号切分, 转16进制再补齐到64位, 拼接 r||s
    - 否则: 拆成前后两半, 每半当hex转10进制, 返回 "left,right"
    """
    if "," in t:
        e = t.index(",")
        r = Xi(t[:e])
        n = Xi(t[e + 1:])
        return pad64(r) + pad64(n)
    else:
        mid = len(t) // 2
        left = Yi(t[:mid])
        right = Yi(t[mid:])
        return f"{left},{right}"


